const produits = [
  { nom: "Clavier", prix: 80, stock: true },
  { nom: "Écran", prix: 240, stock: false },
  { nom: "Souris", prix: 35, stock: true }
];

// 1. On garde seulement les produits disponibles.
const disponibles = produits.filter((produit) => produit.stock);
// 2. On extrait leur prix.
const prix = disponibles.map((produit) => produit.prix);
// 3. On additionne le tableau obtenu, en partant de 0.
const totalDisponible = prix.reduce((total, montant) => total + montant, 0);

console.log(totalDisponible); // 115

